using namespace std;

const long long MOD = 1000003;

// Fast modular exponentiation
long long modpow(long long base, long long exp) {
    long long res = 1 % MOD;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    if (!(cin >> n)) return 0;

    // Number of empty cells = 2 * n^2
    long long ans = (2 % MOD) * (modpow(n % MOD, 2)) % MOD;
    cout << ans << '\n';
    return 0;
}

